<section class="portal-hero staff-hero"><div><span class="eyebrow">Staff Portal · <?= e(date('l, d F')) ?></span><h1>Good <?= date('H')<12?'morning':(date('H')<17?'afternoon':'evening') ?>, <?= e(explode(' ',auth()['name'])[0]) ?></h1><p><?= e($staff['designation_name']?:'Staff member') ?> · <?= e($staff['department_name']?:'Rankers Mind') ?></p></div><a class="button <?= $today&&$today['check_in_at']&&!$today['check_out_at']?'button-danger':'button-success' ?> punch-hero-button" href="<?= url('attendance/punch') ?>"><i class="fa-solid fa-fingerprint"></i> <?= !$today?'Check in':(!$today['check_out_at']?'Check out':'Attendance complete') ?></a></section>
<div class="staff-metrics"><div><span>Today’s status</span><strong><?= e($today['status']??'Not checked in') ?></strong><small><?= $today&&$today['check_in_at']?'In at '.date('g:i A',strtotime($today['check_in_at'])):'Waiting for first punch' ?></small></div><div><span>Present this month</span><strong><?= (int)($attendance['Present']??0)+(int)($attendance['Late']??0) ?> days</strong><small><?= (int)($attendance['Late']??0) ?> late arrivals</small></div><div><span>Month-to-date salary</span><strong><?= $salary?money($salary['net_pay']):'Not calculated' ?></strong><small><?= $salary?'Latest payroll estimate':'Payroll pending' ?></small></div><div><span>Open tasks</span><strong><?= count($tasks) ?></strong><small><?= count(array_filter($tasks,fn($t)=>strtotime($t['due_date'])<strtotime('today'))) ?> overdue</small></div></div>
<div class="portal-grid"><section class="panel span-2"><div class="panel-head"><div><h2>My tasks</h2><p>Assigned work ordered by deadline</p></div><a href="<?= url('tasks') ?>">View all</a></div><div class="task-cards"><?php foreach($tasks as $task):?><a href="<?= url('tasks/'.$task['id']) ?>" class="task-card"><div class="task-card-top"><span class="status-badge <?= status_class($task['priority']) ?>"><?= e($task['priority']) ?></span><span class="<?= strtotime($task['due_date'])<strtotime('today')?'text-danger':'' ?>"><?= e(date('d M',strtotime($task['due_date']))) ?></span></div><h3><?= e($task['title']) ?></h3><p><?= e($task['project_name']?:'General task') ?></p><div class="progress-cell"><span><i style="width:<?= (int)$task['progress'] ?>%"></i></span><small><?= (int)$task['progress'] ?>%</small></div></a><?php endforeach;?><?php if(!$tasks):?><div class="empty-state"><span><i class="fa-solid fa-list-check"></i></span><h3>No open tasks</h3><p>Your assigned work is complete.</p></div><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h2>Leave balance</h2><p><?= date('Y') ?> entitlement</p></div><a href="<?= url('leave/create') ?>">Request</a></div><div class="balance-list"><?php foreach($leaveBalances as $leave):$available=(float)$leave['opening_balance']+(float)$leave['adjustment']-(float)$leave['used_balance'];$allowance=(float)$leave['opening_balance'];?><div><span><?= e($leave['name']) ?></span><strong><?= e($available) ?> days</strong><i><b style="width:<?= $allowance>0?min(100,$available/$allowance*100):0 ?>%"></b></i></div><?php endforeach;?></div></section><section class="panel"><div class="panel-head"><div><h2>Notifications</h2><p>Recent updates</p></div><a href="<?= url('notifications') ?>">View all</a></div><div class="compact-list"><?php foreach($notifications as $item):?><a href="<?= url(ltrim($item['link']?:'notifications','/')) ?>" class="list-row"><span class="notification-dot <?= $item['read_at']?'read':'' ?>"></span><span class="list-main"><strong><?= e($item['title']) ?></strong><small><?= e($item['message']) ?></small></span></a><?php endforeach;?></div></section></div>
<?php require root_path('app/Views/portal/staff-profile.php'); ?>
